(function(e){"use strict";function u(e,t){var n=e+" "+t;if(e!=1)n+="s";return n}function t(){var c=1554056999e3;var i=setInterval(function(){var e=(new Date).getTime();var t=c-e;var n=Math.floor(t/(1e3*60*60*24));var o=Math.floor(t%(1e3*60*60*24)/(1e3*60*60));var r=Math.floor(t%(1e3*60*60)/(1e3*60));var a=Math.floor(t%(1e3*60)/1e3);document.getElementById("march-contest-countdown").innerHTML=u(n,"day")+", "+u(o,"hour")+", "+u(r,"minute")+", "+u(a,"second");if(t<0){clearInterval(i);document.getElementById("march-contest-countdown").innerHTML="CONTEST ENDED"}},1e3)}e(document).ready(function(){e(".modal").modal();setEditorialVoteEventListeners()})})(jQuery);